params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
if($LASTEXITCODE -ne 0){throw 'fetch failed'}
$mainBefore=(git -C $repo rev-parse origin/main).Trim()
$protected=@('main','heaven-bridge','recovery/complete-mod-workflows-20260929')
$deleted=@()
$skipped=@()

function Get-RemoteTip([string]$b){
  $line=(git -C $repo ls-remote origin ("refs/heads/"+$b))
  if(-not $line){return $null}
  return (($line.Trim()) -split '\s+')[0]
}
function Remove-ExactBranch([string]$b,[string]$expected,[string]$reason){
  $actual=Get-RemoteTip $b
  if(-not $actual){$script:skipped += [pscustomobject]@{branch=$b;reason='already-absent'}; return}
  if($actual -ne $expected){$script:skipped += [pscustomobject]@{branch=$b;reason='tip-moved';expected=$expected;actual=$actual}; return}
  $again=Get-RemoteTip $b
  if($again -ne $expected){$script:skipped += [pscustomobject]@{branch=$b;reason='tip-moved-before-delete';expected=$expected;actual=$again}; return}
  git -C $repo push origin --delete $b
  if($LASTEXITCODE -ne 0){throw "delete failed for $b"}
  $script:deleted += [pscustomobject]@{branch=$b;reason=$reason;tip=$expected}
}

# First remove every ordinary remote branch whose current tip is already an ancestor of canonical main.
$remote=@(git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -like 'origin/*' -and $_ -ne 'origin/HEAD' -and $_ -ne 'origin'})
foreach($r in $remote){
  $b=$r.Substring(7)
  if($protected -contains $b){continue}
  $expected=Get-RemoteTip $b
  if(-not $expected){continue}
  git -C $repo merge-base --is-ancestor $expected origin/main 2>$null
  if($LASTEXITCODE -eq 0){
    Remove-ExactBranch $b $expected 'tip-already-contained-in-main'
  }
}

# Explicitly retired PR lanes. Each deletion requires an unchanged tip and a canonical replacement commit still contained in current main.
$explicit=@(
  [pscustomobject]@{branch='agent/fix-release-gate-20260929-0926';expected='5f3adee2a7426f93d59436552c8afa30b06b0d47';requires='f5bb412164d5110d0b46766ff859699d67cee812';reason='PR180 superseded by merged PR181+PR183'},
  [pscustomobject]@{branch='fix/v8810-release-gate-regressions-20260929';expected='3481487c651aa8b7369a475db22df8b93f1a5bec';requires='5f70de648db95c542d556fb89a61a461e2a25268';reason='merged PR181 delivery branch'},
  [pscustomobject]@{branch='fix/release-gate-remaining-blockers-20260929';expected='0bca2d24d37cff1e1f1fb0918cd156e918d3a811';requires='5f70de648db95c542d556fb89a61a461e2a25268';reason='PR182 explicitly superseded by merged PR181'},
  [pscustomobject]@{branch='fix/crash-interaction-confirmation-20260929';expected='4813132b8a32ff8456a0eaa80f9ff2d280a35955';requires='f5bb412164d5110d0b46766ff859699d67cee812';reason='merged PR183 delivery branch'},
  [pscustomobject]@{branch='fix/rest-updater-publication-20260929';expected='b358576ecca192117c7c3f0c46f44f273f744274';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR184 failed syntax lane retired in favor of canonical release repair'},
  [pscustomobject]@{branch='fix/heaven-release-publisher-no-gh-20260929';expected='5aa3bca3b99c53527789522a240d0eee6e7d45ab';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR186 superseded release-publisher lane'},
  [pscustomobject]@{branch='fix/updater-rest-publication-20260929';expected='f337608722149ce3d9e9c20e17bada8a6fb7dc8b';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR187 explicitly superseded'},
  [pscustomobject]@{branch='fix/repair-corrupt-release-gate-and-publisher-20260929';expected='acf25b9f8c134a38a6477d75b871090024c750db';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR188 superseded by verified canonical main release path'},
  [pscustomobject]@{branch='fix/clean-heaven-publication-workflow-20260929';expected='e987673eaa7c16cd3d6aba51929d2da43d3ff5a9';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR189 folded into later canonical repair'},
  [pscustomobject]@{branch='fix/heaven-rest-release-publication-20260929';expected='f4f4c65420d9f8e757626e66b86f626cbed1207e';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR190 superseded release-publisher lane'},
  [pscustomobject]@{branch='fix/release-runtime-cleanup-20260929';expected='fac8987b1f8090647ceac2bc66f02d8995eaa4c5';requires='25f9ce08e40812256ac5342ec9976207e58719a2';reason='PR191 retired after verified canonical main release path'},
  [pscustomobject]@{branch='feature/public-updater-feed-20260929';expected='8c00e278f0603c86f566e71437a2be22440c7a57';requires='3eeb683fbf517192009111503c3b306d586d9f18';reason='PR192 functionality consolidated into merged PR194'},
  [pscustomobject]@{branch='feature/public-updater-mirror-20260929';expected='c6f05e1d86a0bdff739bf70c0843c577135ffd70';requires='3eeb683fbf517192009111503c3b306d586d9f18';reason='PR193 mirror work consolidated into merged PR194'},
  [pscustomobject]@{branch='feature/public-updater-channel-final-20260929';expected='c5d2c13de55a52a04ba6d39da4a15d3fbe8cd34a';requires='3eeb683fbf517192009111503c3b306d586d9f18';reason='merged PR194 delivery branch'},
  [pscustomobject]@{branch='fix/public-updater-mirror-clean-20260929';expected='822c5d7656e96848bbe0e8884ce0ff750b18c87d';requires='3eeb683fbf517192009111503c3b306d586d9f18';reason='PR195 duplicate/subset of merged PR194 with no unique code'}
)
foreach($x in $explicit){
  if($deleted.branch -contains $x.branch){continue}
  $actual=Get-RemoteTip $x.branch
  if(-not $actual){$skipped += [pscustomobject]@{branch=$x.branch;reason='already-absent'};continue}
  if($actual -ne $x.expected){$skipped += [pscustomobject]@{branch=$x.branch;reason='tip-moved';expected=$x.expected;actual=$actual};continue}
  git -C $repo cat-file -e ($x.requires+'^{commit}') 2>$null
  if($LASTEXITCODE -ne 0){$skipped += [pscustomobject]@{branch=$x.branch;reason='required-replacement-commit-missing';requires=$x.requires};continue}
  git -C $repo merge-base --is-ancestor $x.requires origin/main 2>$null
  if($LASTEXITCODE -ne 0){$skipped += [pscustomobject]@{branch=$x.branch;reason='required-replacement-not-in-current-main';requires=$x.requires};continue}
  Remove-ExactBranch $x.branch $x.expected $x.reason
}

git -C $repo fetch origin --prune
$mainAfter=(git -C $repo rev-parse origin/main).Trim()
$remaining=@(git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -like 'origin/*' -and $_ -ne 'origin/HEAD' -and $_ -ne 'origin'} | ForEach-Object {$_.Substring(7)} | Sort-Object)
[pscustomobject]@{main_before=$mainBefore;main_after=$mainAfter;deleted=$deleted;skipped=$skipped;remaining=$remaining} | ConvertTo-Json -Depth 8
